    # Helper function to get neighbors and their weights
    def get_neighbors(node, graph):
        return [(neighbor, weight) for neighbor, weight in graph[node] if neighbor != source]

    # Bidirectional BFS
    def bidirectional_bfs(graph, source, target):
        # Enqueue the start node for both forward and backward searches
        forward_queue = deque([(source, [])])
        backward_queue = deque([(target, [])])

        forward_visited = {source}
        backward_visited = {target}

        while forward_queue and backward_queue:
            # Forward Search
            forward_node, forward_path = forward_queue.popleft()
            for neighbor, weight in get_neighbors(forward_node, graph):
                if neighbor not in forward_visited:
                    forward_path.append(neighbor)
                    forward_visited.add(neighbor)
                    if neighbor == target:
                        return sum(weight for _, weight in forward_path), forward_path
                    forward_queue.append((neighbor, forward_path.copy()))

            # Backward Search
            backward_node, backward_path = backward_queue.popleft()
            for neighbor, weight in get_neighbors(backward_node, graph):
                if neighbor not in backward_visited:
                    backward_path.append(neighbor)
                    backward_visited.add(neighbor)
                    if neighbor == source:
                        return sum(weight for _, weight in backward_path), backward_path[::-1]
                    backward_queue.append((neighbor, backward_path.copy()))

        return float("inf"), None

    # Perform the bidirectional BFS
    return bidirectional_bfs(graph, source, target)

